def unique_jobs(rows):
    seen = set()
    result = []

    for r in rows:
        source = r.get('source')
        source_id = r.get('source_id', '') or ''

        if source and source_id:
            key = (source, source_id)
            if key not in seen:
                seen.add(key)
                result.append(r)
        else:
            # Row without valid source/source_id - keep separately
            key = ('_missing_source_', '_missing_source_id_')
            if key not in seen:
                seen.add(key)
                result.append(r)

    return result
